\node (step1) [process, below of=start] {Mix eggs, milk, and cinnamon};
\node (step2) [process, below of=step1] {Dip bread in mixture};
\node (step3) [decision, below of=step2, yshift=-0.5cm] {Bread soaked?};
\node (step4) [process, below of=step3, yshift=-0.5cm] {Cook bread on griddle};
\node (step5) [decision, below of=step4, yshift=-0.5cm] {Both sides cooked?};
\node (step6) [process, below of=step5, yshift=-0.5cm] {Serve with toppings};
\node (stop) [startstop, below of=step6] {Stop};
\draw [arrow] (start) -- (step1);
\draw [arrow] (step1) -- (step2);
\draw [arrow] (step2) -- (step3);
\draw [arrow] (step3) -- node[anchor=east] {yes} (step4);
\draw [arrow] (step4) -- (step5);
\draw [arrow] (step5) -- node[anchor=east] {yes} (step6);
\draw [arrow] (step3) -| node[anchor=south] {no} ([xshift=-1.5cm]step3.west) |- ([yshift=-0.5cm]step1.south) -- (step1);
\draw [arrow] (step5) -| node[anchor=south] {no} ([xshift=1.5cm]step5.east) |- ([yshift=-0.5cm]step4.south) -- (step4);
