Can you identify the odd one out based on its brewing process? Here is a list of coffee types:
Espresso
French press
Drip
Cappuccino
Instant
Americano
Which one deviates from the others? 
Here is a sample Go code that can help you identify the unique brewing process:
package main
import (
    "fmt"
    "strings"
)
func main() {
    coffees := []string{"Espresso", "French press", "Drip", "Cappuccino", "Instant", "Americano"}
    uniqueProcess := ""
    for _, coffee := range coffees {
        if strings.Contains(coffee, "instant") {
            uniqueProcess = "Instant"
            break
        } else if strings.Contains(coffee, "espresso") {
            uniqueProcess = "Espresso"
            break
        } else if strings.Contains(coffee, "french press") {
            uniqueProcess = "French press"
            break
        } else if strings.Contains(coffee, "drip") {
            uniqueProcess = "Drip"
            break
        } else if strings.Contains(coffee, "americano") {
            uniqueProcess = "Americano"
            break
        } else if strings.Contains(coffee, "cappuccino") {
            uniqueProcess = "Cappuccino"
            break
        }
    }
    fmt.Println(uniqueProcess, "is the odd one out based on its unique brewing process.")
}

