```
import UIKit
class BarChartViewController: UIViewController {
    // Define the data for the chart
    let languages = ["Java", "Python", "JavaScript", "C++", "Swift"]
    let percentages = [30, 25, 20, 15, 10]
    let users = [300, 250, 200, 150, 100]
    // Define the colors for the bars
    let colors = [UIColor.red, UIColor.blue, UIColor.green, UIColor.orange, UIColor.purple]
    // Define the chart view
    var chartView: UIView!
    override func viewDidLoad() {
        super.viewDidLoad()
        // Create the chart view
        chartView = UIView(frame: CGRect(x: 0, y: 0, width: view.frame.width, height: view.frame.height))
        view.addSubview(chartView)
        // Calculate the maximum number of users
        let maxUsers = users.max()!
        // Calculate the bar width and spacing
        let barWidth = chartView.frame.width / CGFloat(languages.count + 1)
        let barSpacing = barWidth / 2
        // Create the bars
        for i in 0..<languages.count {
            // Calculate the bar height
            let barHeight = chartView.frame.height * CGFloat(percentages[i]) / 100
            // Create the bar view
            let barView = UIView(frame: CGRect(x: barSpacing + CGFloat(i) * barWidth, y: chartView.frame.height - barHeight, width: barWidth, height: barHeight))
            barView.backgroundColor = colors[i]
            // Add the percentage label
            let percentageLabel = UILabel(frame: CGRect(x: 0, y: 0, width: barWidth, height: barHeight))
            percentageLabel.text = "\(percentages[i])%"
            percentageLabel.textColor = UIColor.white
            percentageLabel.textAlignment = .center
            barView.addSubview(percentageLabel)
            // Add the user label
            let userLabel = UILabel(frame: CGRect(x: 0, y: barHeight, width: barWidth, height: chartView.frame.height - barHeight))
            userLabel.text = "\(users[i]) users"
            userLabel.textColor = UIColor.black
            userLabel.textAlignment = .center
            barView.addSubview(userLabel)
            // Add the bar view to the chart view
            chartView.addSubview(barView)
            // Add the tap gesture recognizer
            let tapGestureRecognizer = UITapGestureRecognizer(target: self, action: #selector(barTapped(_:)))
            barView.addGestureRecognizer(tapGestureRecognizer)
            // Add the hover gesture recognizer
            let hoverGestureRecognizer = UILongPressGestureRecognizer(target: self, action: #selector(barHovered(_:)))
            barView.addGestureRecognizer(hoverGestureRecognizer)
        }
    }
    // Sort the bars in ascending or descending order based on the number of users
    func sortBars(ascending: Bool) {
        let sortedUsers = ascending ? users.sorted() : users.sorted().reversed()
        for i in 0..<languages.count {
            let j = users.firstIndex(of: sortedUsers[i])!
            let barView = chartView.subviews[j]
            chartView.exchangeSubview(at: i, withSubviewAt: j)
        }
    }
    // Handle the bar tap gesture
    @objc func barTapped(_ sender: UITapGestureRecognizer) {
        if let barView = sender.view {
            let j = chartView.subviews.firstIndex(of: barView)!
            let language = languages[j]
            let users = self.users[j]
            let message = "\(language) has \(users) users."
            let alert = UIAlertController(title: "Bar Tapped", message: message, preferredStyle: .alert)
            alert.addAction(UIAlertAction(title: "OK", style: .default, handler: nil))
            present(alert, animated: true, completion: nil)
        }
    }
    // Handle the bar hover gesture
    @objc func barHovered(_ sender: UILongPressGestureRecognizer) {
        if let barView = sender.view {
            let j = chartView.subviews.firstIndex(of: barView)!
            let color = colors[j].withAlphaComponent(0.5)
            barView.backgroundColor = color
        }
    }
}
```
This code creates a `BarChartViewController` that displays a bar chart with the given data. The chart has bars for each programming language, color-coded based on the given colors. The bars are sorted based on the number of users in ascending or descending order when the user taps the sort button. When the user taps a bar, an alert is displayed with the language and number of users. When the user hovers over a bar, the color of the bar changes to a brighter shade of the same color.

Certainly! Java is a versatile programming language that can be used for a wide range of applications, including simulating the spread of COVID-19 in a school setting. Here is an example Java code that can simulate the spread of COVID-19 in a hypothetical school setting, taking into account factors such as student and staff interactions, ventilation, and mask usage:
```
import java.util.*;
public class CovidSimulator {
    public static void main(String[] args) {
        int numStudents = 1000;
        int numStaff = 100;
        int numDays = 180;
        double transmissionRate = 0.02;
        double maskEffectiveness = 0.8;
        double ventilationEffectiveness = 0.5;
        double testingFrequency = 0.1;
        double contactTraceRate = 0.8;
        int isolationCapacity = 20;

        // Initialize the population
        Person[] population = new Person[numStudents + numStaff];
        for (int i = 0; i < numStudents; i++) {
            population[i] = new Person("Student " + i, false);
        }
        for (int i = numStudents; i < numStudents + numStaff; i++) {
            population[i] = new Person("Staff " + (i - numStudents), true);
        }

        // Initialize the school environment
        School school = new School(population, transmissionRate, maskEffectiveness, ventilationEffectiveness, testingFrequency, contactTraceRate, isolationCapacity);

        // Simulate the spread of COVID-19
        for (int i = 0; i < numDays; i++) {
            school.simulateDay();
            System.out.println("Day " + (i + 1) + ": " + school.getNumInfected() + " infected");
        }

        // Analyze the effectiveness of the safety measures
        System.out.println("Mask usage effectiveness: " + school.getMaskEffectiveness());
        System.out.println("Ventilation effectiveness: " + school.getVentilationEffectiveness());
        System.out.println("Testing frequency: " + school.getTestingFrequency());
        System.out.println("Contact tracing rate: " + school.getContactTraceRate());
        System.out.println("Isolation capacity: " + school.getIsolationCapacity());
    }
}
class Person {
    private String name;
    private boolean isStaff;
    private boolean isInfected;
    private boolean isIsolated;
    private int daysInfected;

    public Person(String name, boolean isStaff) {
        this.name = name;
        this.isStaff = isStaff;
        this.isInfected = false;
        this.isIsolated = false;
        this.daysInfected = 0;
    }

    public String getName() {
        return name;
    }

    public boolean isStaff() {
        return isStaff;
    }

    public boolean isInfected() {
        return isInfected;
    }

    public void setInfected(boolean isInfected) {
        this.isInfected = isInfected;
    }

    public boolean isIsolated() {
        return isIsolated;
    }

    public void setIsolated(boolean isIsolated) {
        this.isIsolated = isIsolated;
    }

    public int getDaysInfected() {
        return daysInfected;
    }

    public void setDaysInfected(int daysInfected) {
        this.daysInfected = daysInfected;
    }
}
class School {
    private Person[] population;
    private double transmissionRate;
    private double maskEffectiveness;
    private double ventilationEffectiveness;
    private double testingFrequency;
    private double contactTraceRate;
    private int isolationCapacity;
    private List<Person> infectedList;
    private List<Person> isolatedList;

    public School(Person[] population, double transmissionRate, double maskEffectiveness, double ventilationEffectiveness, double testingFrequency, double contactTraceRate, int isolationCapacity) {
        this.population = population;
        this.transmissionRate = transmissionRate;
        this.maskEffectiveness = maskEffectiveness;
        this.ventilationEffectiveness = ventilationEffectiveness;
        this.testingFrequency = testingFrequency;
        this.contactTraceRate = contactTraceRate;
        this.isolationCapacity = isolationCapacity;
        this.infectedList = new ArrayList<>();
        this.isolatedList = new ArrayList<>();
    }

    public void simulateDay() {
        // Randomly select people for testing
        for (Person person : population) {
            if (Math.random() < testingFrequency) {
                if (person.isInfected()) {
                    person.setIsolated(true);
                    isolatedList.add(person);
                }
            }
        }

        // Perform contact tracing
        for (Person person : infectedList) {
            if (Math.random() < contactTraceRate) {
                for (Person contact : getContacts(person)) {
                    if (!contact.isInfected() && !contact.isIsolated()) {
                        double transmissionProb = transmissionRate * (1 - maskEffectiveness) * (1 - ventilationEffectiveness);
                        if (Math.random() < transmissionProb) {
                            contact.setInfected(true);
                            infectedList.add(contact);
                        }
                    }
                }
            }
        }

        // Update infection status and days infected
        for (Person person : population) {
            if (person.isInfected()) {
                person.setDaysInfected(person.getDaysInfected() + 1);
                if (person.getDaysInfected() >= 14) {
                    person.setInfected(false);
                    person.setDaysInfected(0);
                    if (person.isIsolated()) {
                        person.setIsolated(false);
                        isolatedList.remove(person);
                    }
                    infectedList.remove(person);
                }
            }
        }

        // Randomly select people to become infected
        for (Person person : population) {
            if (!person.isInfected() && !person.isIsolated()) {
                double transmissionProb = transmissionRate * (1 - maskEffectiveness) * (1 - ventilationEffectiveness);
                if (Math.random() < transmissionProb) {
                    person.setInfected(true);
                    infectedList.add(person);
                }
            }
        }
    }

    private List<Person> getContacts(Person person) {
        List<Person> contacts = new ArrayList<>();
        for (Person other : population) {
            if (other != person && !other.isIsolated()) {
                if (other.isStaff() && person.isStaff()) {
                    contacts.add(other);
                } else if (!other.isStaff() && !person.isStaff()) {
                    contacts.add(other);
                }
            }
        }
        return contacts;
    }

    public int getNumInfected() {
        int numInfected = 0;
        for (Person person : population) {
            if (person.isInfected()) {
                numInfected++;
            }
        }
        return numInfected;
    }

    public double getMaskEffectiveness() {
        return maskEffectiveness;
    }

    public double getVentilationEffectiveness() {
        return ventilationEffectiveness;
    }

    public double getTestingFrequency() {
        return testingFrequency;
    }

    public double getContactTraceRate() {
        return contactTraceRate;
    }

    public int getIsolationCapacity() {
        return isolationCapacity;
    }
}
```
This code simulates the spread of COVID-19 in a school setting by randomly selecting people for testing, performing contact tracing, and updating infection status and days infected. It also incorporates various safety measures, such as mask usage, ventilation, testing, contact tracing, and isolation rooms. 
To analyze the effectiveness of these measures in reducing the spread of COVID-19 in the simulated school environment using Java's data visualization tools, you can use a variety of libraries such as JFreeChart or JavaFX Charts. These libraries allow you to create various types of charts and graphs, such as line charts, bar charts, and pie charts, to visualize the data collected from the simulation. You can plot the number of infected individuals over time, and compare the results with and without the safety measures in place to determine their effectiveness.

