\usepackage{pgf}
\begin{document}
\pgfmathsetmacro{\n}{10}
\def\fib{1,1}
\pgfmathsetmacro{\sum}{2}
\foreach \i in {3,...,\n}{
    \pgfmathsetmacro{\next}{\fib[\i-2]+\fib[\i-3]}
    \xdef\fib{\fib,\next}
    \pgfmathsetmacro{\sum}{\sum+\next}
}
\pgfmathhex{\sum}
\edef\hexsum{\pgfmathresult}
