Range range = worksheet.UsedRange;
for (int row = 2; row <= range.Rows.Count; row++)
{
    DataRow dataRow = table.NewRow();
    for (int col = 1; col <= range.Columns.Count; col++)
    {
        if (row == 2)
        {
            // Create the columns for the DataTable
