            // Add the data to the DataTable
            dataRow[col - 1] = range.Cells[row, col].Value2.ToString();
        }
    }
    if (row != 2)
    {
        table.Rows.Add(dataRow);
    }
}
// Close the Excel file
workbook.Close(false);
excel.Quit();
```
