  }
  echo "</table>";
} else {
  echo "0 results";
}
$conn->close();
?>
How can I modify this code to include pagination?

output:
Here is an example of how you can modify the code to include pagination:
```
<?php
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "database_name";
// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);
// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}
// Define how many results you want per page
$results_per_page = 10;
// Find out how many rows are in the table
$sql = "SELECT COUNT(*) AS total FROM table_name";
$result = $conn->query($sql);
$row = $result->fetch_assoc();
$total_results = $row['total'];
// Calculate total number of pages
$total_pages = ceil($total_results / $results_per_page);
// Check if page parameter is set
if (!isset($_GET['page'])) {
    $page = 1;
} else {
    $page = $_GET['page'];
}
// Calculate the starting limit for the results
$starting_limit = ($page - 1) * $results_per_page;
// Retrieve the data from the table with the limit and offset
$sql = "SELECT * FROM table_name LIMIT $starting_limit, $results_per_page";
$result = $conn->query($sql);
if ($result->num_rows > 0) {
    echo "<table><tr><th>Column 1</th><th>Column 2</th></tr>";
    // output data of each row
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>".$row["column1"]."</td><td>".$row["column2"]."</td></tr>";
    }
    echo "</table>";
    // Display pagination links
    echo "<div class='pagination'>";
    for ($i = 1; $i <= $total_pages; $i++) {
        echo "<a href='?page=".$i."'>".$i."</a>";
    }
    echo "</div>";
} else {
    echo "0 results";
}
$conn->close();
?>
```
In this code, we first define how many results we want to display per page. We then retrieve the total number of rows in the table and calculate the total number of pages based on the results per page.
We check if the page parameter is set in the URL and calculate the starting limit for the results based on the current page. We then retrieve the data from the table with the limit and offset.
We display the results in a table and add pagination links at the bottom of the page. The links are generated using a loop that goes from 1 to the total number of pages and creates a link for each page.
You can style the pagination links using CSS to make them look like buttons or links.

