            int[,,,,] subArr = new int[5, 5, 5, 5, 5];
            for (int i = 0; i < 5; i++)
            {
                for (int j = 0; j < 5; j++)
                {
                    for (int k = 0; k < 5; k++)
                    {
                        for (int l = 0; l < 5; l++)
                        {
                            for (int m = 0; m < 5; m++)
                            {
                                if (arr[i, j, k, l, m] > minVal)
                                {
                                    subArr[i, j, k, l, m] = arr[i, j, k, l, m];
                                }
                            }
                        }
                    }
                }
            }
            return subArr;
        }
