model.add(Conv2D<Float>(filterShape: (3, 3, 1, 32), padding: .same, activation: relu, inputShape: (28, 28, 1)))
model.add(MaxPool2D<Float>(poolSize: (2, 2), strides: (2, 2)))
model.add(Conv2D<Float>(filterShape: (3, 3, 32, 64), padding: .same, activation: relu))
model.add(MaxPool2D<Float>(poolSize: (2, 2), strides: (2, 2)))
