        let yb = yTrain.slice(lowerBounds: [i, 0], upperBounds: [i + batchSize, 10])
        let (lossValue, grad) = valueWithGradient(at: model) { model -> Tensor<Float> in
            let logits = model(xb)
            let lossValue = loss(predicted: logits, expected: yb)
            return lossValue
        }
        optimizer.update(&model, along: grad)
        let logits = model(xb)
        epochLoss += loss(predicted: logits, expected: yb).scalarized()
        epochAccuracy += accuracy(predicted: logits, expected: yb)
        batchCount += 1
    }
    epochLoss /= Float(batchCount)
    epochAccuracy /= Float(batchCount)
    print("[Epoch \(epoch)] Loss: \(epochLoss), Accuracy: \(epochAccuracy)")
