func relu(_ x: Tensor<Float>) -> Tensor<Float> {
    max(0, x)
}
func softmax(_ x: Tensor<Float>) -> Tensor<Float> {
    let exps = exp(x - x.max(alongAxes: -1))
    return exps / exps.sum(alongAxes: -1)
}
func softmaxCrossEntropy(predicted: Tensor<Float>, expected: Tensor<Float>) -> Tensor<Float> {
