    let yTest = parseLabels(data: testLabels, count: testImageCount, labelRange: labelRange)
    return (xTrain: xTrain, yTrain: yTrain, xTest: xTest, yTest: yTest)
}
func parseImages(data: Data, count: Int, rowCount: Int, colCount: Int) -> Tensor<Float> {
    var tensor = Tensor<Float>(zeros: [count, rowCount, colCount])
    for i in 0..<count {
