func parseLabels(data: Data, count: Int, labelRange: Range<Int>) -> Tensor<Float> {
    var tensor = Tensor<Float>(zeros: [count, labelRange.count])
    for i in 0..<count {
        tensor[i, Int(data[8 + i])] = 1
    }
    return tensor
}
