        double[] proximity = {10, 20, 15, 25, 30, 35, 40, 45, 50, 55};
        // Create regression model
        OLSMultipleLinearRegression regression = new OLSMultipleLinearRegression();
        double[][] predictors = new double[temperature.length][4];
        for (int i = 0; i < temperature.length; i++) {
            predictors[i][0] = 1;  // Intercept
            predictors[i][1] = species[i];
            predictors[i][2] = density[i];
            predictors[i][3] = proximity[i];
        }
        regression.newSampleData(temperature, predictors);
        // Print model coefficients
