        System.out.println("Species coefficient: " + coefficients[1]);
        System.out.println("Density coefficient: " + coefficients[2]);
        System.out.println("Proximity coefficient: " + coefficients[3]);
        // Perform hypothesis test on coefficients
        double[] standardErrors = regression.estimateRegressionParametersStandardErrors();
        double[] tStats = new double[4];
        for (int i = 0; i < 4; i++) {
            tStats[i] = coefficients[i] / standardErrors[i];
        }
        double[] pValues = new double[4];
        for (int i = 0; i < 4; i++) {
            pValues[i] = 2 * (1 - StudentT.cumulativeProbability(Math.abs(tStats[i]), temperature.length - 4));
        }
        System.out.println("Species t-statistic: " + tStats[1] + ", p-value: " + pValues[1]);
        System.out.println("Density t-statistic: " + tStats[2] + ", p-value: " + pValues[2]);
        System.out.println("Proximity t-statistic: " + tStats[3] + ", p-value: " + pValues[3]);
        // Calculate R-squared value
        double rSquared = regression.calculateRSquared();
        System.out.println("R-squared: " + rSquared);
    }
}
