Here is an example Swift code that utilizes a for loop and a boolean variable to determine if a number is a prime number:
func isPrimeNumber(_ number: Int) -> Bool {
    if number <= 1 {
        return false
    }

    for i in 2..<number {
        if number % i == 0 {
            return false
        }
    }

    return true
}
